/**
 * @summary Submit one answer and update LP/XP/progress
 */
export const submitRankedAnswerBodyElapsedSecondsMin = 0;
export const submitRankedAnswerBodyElapsedSecondsMax = 14400;

export const submitRankedAnswerBodyDisplayPositionMax = 99;

export const SubmitRankedAnswerBody = zod.object({
  passage_id: zod.string(),
  question_id: zod.number(),
  selected_answer: zod.string(),
  local_date: zod.coerce.date().optional(),
  elapsed_seconds: zod
    .number()
    .min(submitRankedAnswerBodyElapsedSecondsMin)
    .max(submitRankedAnswerBodyElapsedSecondsMax)
    .optional(),
  display_position: zod
    .number()
    .min(1)
    .max(submitRankedAnswerBodyDisplayPositionMax)
    .optional(),
});

export const SubmitRankedAnswerResponse = zod.object({
  progress: zod.object({
    user_id: zod.string(),
    lifetime_xp: zod.number(),
    ranked_points: zod.number(),
    current_rank: zod.string(),
    total_questions_answered: zod.number(),
    total_correct: zod.number(),
    total_incorrect: zod.number(),
    current_practice_streak_days: zod.number(),
    best_practice_streak_days: zod.number(),
    last_practice_date_local: zod.coerce.date().nullable(),
    created_at: zod.coerce.date(),
    updated_at: zod.coerce.date(),
  }),
  current_streak_days: zod.number(),
  next_rank_progress: zod.object({
    currentRank: zod.string(),
    nextRank: zod.string().nullable(),
    pointsIntoCurrentRank: zod.number(),
    pointsNeededForNextRank: zod.number(),
    progressPercent: zod.number(),
  }),
  answer_result: zod.object({
    isCorrect: zod.boolean(),
    selectedAnswer: zod.string(),
    correctAnswer: zod.string(),
    rankedPointsBefore: zod.number(),
    rankedPointsAfter: zod.number(),
    rankedPointDelta: zod.number(),
    lifetimeXpBefore: zod.number(),
    lifetimeXpAfter: zod.number(),
    xpDelta: zod.number(),
    rankBefore: zod.string(),
    rankAfter: zod.string(),
    rankedUp: zod.boolean(),
    rankedDown: zod.boolean(),
  }),
  question_timing: zod
    .object({
      elapsed_seconds: zod.number().optional(),
      display_position: zod.number().optional(),
      source_question_id: zod.number().optional(),
      order_index: zod.number().optional(),
    })
    .nullable(),
});

